class Solution {
    public boolean isValidSequence(TreeNode root, int[] arr) {
        Deque<Object[]> q = new ArrayDeque<>();
        q.offer(new Object[]{root, 0});
        while (!q.isEmpty()) {
            Object[] cur = q.poll();
            TreeNode node = (TreeNode) cur[0];
            int i = (Integer) cur[1];
            if (node == null || node.val != arr[i]) continue;
            if (i == arr.length - 1) {
                if (node.left == null && node.right == null) return true;
                continue;
            }
            if (node.left != null) q.offer(new Object[]{node.left, i + 1});
            if (node.right != null) q.offer(new Object[]{node.right, i + 1});
        }
        return false;
    }
}

